import java.util.*;

class Solution {
    public int[] tightestWindow(int[][] lists) {
        // heap entries: {value, listIndex, position}
        PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        int max = Integer.MIN_VALUE;
        for (int i = 0; i < lists.length; i++) {
            heap.offer(new int[]{lists[i][0], i, 0});
            max = Math.max(max, lists[i][0]);
        }
        int bestLo = heap.peek()[0], bestHi = max;
        while (true) {
            int[] top = heap.poll();
            int v = top[0], i = top[1], j = top[2];
            if (max - v < bestHi - bestLo) { bestLo = v; bestHi = max; }  // strictly narrower
            if (j + 1 == lists[i].length) break;                          // this list is used up
            int nv = lists[i][j + 1];
            max = Math.max(max, nv);
            heap.offer(new int[]{nv, i, j + 1});
        }
        return new int[]{bestLo, bestHi};
    }
}

