function tightestWindow(lists) {
  const all = []; lists.forEach((l, i) => l.forEach(v => all.push([v, i])));
  all.sort((p, q) => p[0] - q[0]);
  const k = lists.length, cnt = new Array(k).fill(0); let have = 0, L = 0, best = null;
  for (let r = 0; r < all.length; r++) {
    if (cnt[all[r][1]]++ === 0) have++;
    while (have === k) {
      const lo = all[L][0], hi = all[r][0];
      if (best === null || hi - lo < best[1] - best[0]) best = [lo, hi];
      if (--cnt[all[L][1]] === 0) have--; L++;
    }
  }
  return best;
}
